import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 6353c49:
# &packet.PlayerLocation{Type: packet.PlayerLocationTypeCoordinates, EntityUniqueID: 7,
#   Position: mgl32.Vec3{1, 2, 3}}
V1001_COORDINATES = bytes.fromhex("000000000e0000803f0000004000004040")

# generated by gophertunnel 6353c49:
# &packet.PlayerLocation{Type: packet.PlayerLocationTypeHide, EntityUniqueID: 7}
V1001_HIDDEN = bytes.fromhex("010000000e")

# generated by gophertunnel b8bd735:
# &packet.PlayerLocation{Type: packet.PlayerLocationTypeCoordinates, EntityUniqueID: 7,
#   Position: mgl32.Vec3{1, 2, 3}}
V2168_COORDINATES = bytes.fromhex("0e00000000803f0000004000004040")

# generated by gophertunnel b8bd735:
# &packet.PlayerLocation{Type: packet.PlayerLocationTypeHide, EntityUniqueID: 7}
V2168_HIDDEN = bytes.fromhex("0e0102")

V1001_TYPE = v1001.PlayerLocationPacket.Type
V2168_LOCATION = v2168.PlayerLocationPacket

GOLDENS = [
    pytest.param(
        v1001.PlayerLocationPacket(
            type=V1001_TYPE.PLAYER_LOCATION_COORDINATES, id=7, pos=v1001.Vec3(x=1.0, y=2.0, z=3.0)
        ),
        V1001_COORDINATES,
        id="v1001-coordinates",
    ),
    pytest.param(
        v1001.PlayerLocationPacket(type=V1001_TYPE.PLAYER_LOCATION_HIDE, id=7),
        V1001_HIDDEN,
        id="v1001-hidden",
    ),
    pytest.param(
        V2168_LOCATION(
            id=7,
            location=V2168_LOCATION.CoordinatesLocation(
                type=V2168_LOCATION.Type.PLAYER_LOCATION_COORDINATES, pos=v2168.Vec3(x=1.0, y=2.0, z=3.0)
            ),
        ),
        V2168_COORDINATES,
        id="v2168-coordinates",
    ),
    pytest.param(
        V2168_LOCATION(id=7, location=V2168_LOCATION.HiddenLocation(type=V2168_LOCATION.Type.PLAYER_LOCATION_HIDE)),
        V2168_HIDDEN,
        id="v2168-hidden",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_player_location_is_packet_326(version):
    assert version.PACKETS[326] is version.PlayerLocationPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_location_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_location_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_v1001_drops_the_position_when_the_player_is_hidden():
    packet = v1001.PlayerLocationPacket(type=V1001_TYPE.PLAYER_LOCATION_HIDE, id=7, pos=v1001.Vec3(x=1.0, y=2.0, z=3.0))
    assert bytes(packet) == V1001_HIDDEN


def test_v2168_rejects_a_v1001_hidden_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerLocationPacket.from_bytes(V1001_HIDDEN)


def test_v1001_rejects_a_v2168_hidden_body():
    with pytest.raises(ValueError, match="at byte"):
        v1001.PlayerLocationPacket.from_bytes(V2168_HIDDEN)
